   public static final String sql_getFinTrType="SELECT TR_ID,TR_DESC AS TR_SDESC FROM FIN_TR_TYPE WHERE TR_SDESC_GBL='TRREQTYPE$A' ORDER BY TR_ID";
   public static final String sql_getEmployee="SELECT EMP_NO,EMP_FST_NAME,NVL(EMP_MDL_NAME,' ') AS EMP_MDL_NAME,NVL(EMP_LST_NAME,' ') AS EMP_LST_NAME FROM HRM_EMPLOYEE WHERE EMP_STATUS_FLG='A'AND EMP_UNIT_ID=? ORDER BY EMP_NO";
