   public static final String sql_getNewAdvId="SELECT nvl(FIN_TR_ADV_HDR_NUM_SEQ.NEXTVAL,0) AS SEQ_NO,nvl(get_id(?,'FIN_TR_ADV_HDR'),0) AS NEXTID FROM DUAL";

   public static final String VALIDATE_VH_DATE = "select 'Y' result from dual where " + 
    "to_date(?, 'dd/mm/yyyy') >= (select to_char(nvl(max(posting_dt), to_date(?, 'dd/mm/yyyy'))) from FIN_VOUCHER_HDR where loc_id = ? " +
    "and txn_status_gbl = 'VHSTAT$6')";

