   public static final String sql_RetrieveRecordsForEdit_Dtl_IDS="SELECT VOUCHER_DTL_ID,VOUCHER_TXN_NO FROM FIN_VOUCHER_DTL WHERE VOUCHER_ID=? ORDER BY VOUCHER_DTL_ID"; // Added USI CODE WHEN DOING THE RECEIPT SCREEN    

